def make_pages():
    pages=[];current=None
    def begin(slug,title,h1,desc,answer='',diagram='run',alt='',caption='',lang='en',kind='content'):
        nonlocal current
        current=dict(slug=slug,title=title,h1=h1,desc=desc,answer=answer,parts=[],sources=[],related=[],diagram=diagram,diagram_alt=alt,diagram_caption=caption,lang=lang,kind=kind)
        pages.append(current);return current
    def r(key):
        if key not in current['sources']:current['sources'].append(key)
        return ref(current['sources'].index(key)+1)
    def s(id,title,body):current['parts'].append((id,title,body))
    def links(*items):current['related']=list(items)
    def limit(extra=''):
        return '<p class="note">Rules below refer to JPTER78’s source snapshot <strong>680c3e12c670</strong>, reviewed October 26, 2026. Other hosted editions and native ports can differ. We have not completed a comparative run or verified a universal fix. '+extra+'</p>'
    def image_alt(*labels):return ' → '.join(labels)

    home=begin('','Poke Survivor Guide: Start, Builds, Saves & Co-op','PokéSurvivor field guide','Find the original Poke Survivor game and clear guides to controls, physical and special builds, saves, mobile play, co-op, tickets and rifts.',diagram=None)
    home['home']=True
    home['body']=f'''<header class="ps-hero" id="guide"><div><p class="eyebrow">Independent player guide / JPTER78’s game</p><h1>PokéSurvivor.<br><span>Make the next move.</span></h1><p>PokéSurvivor is a free browser survival fan game: keep moving while your active move attacks. Start with the right game, protect your progress, then build around the moves you actually use.{r('guide')}</p><div class="actions"><a class="button hero-play" href="{P}play/">▶ Play online</a>{ext('https://pokesurvivor.com/en/','Original: pokesurvivor.com')}<a class="button" href="{P}beginners-guide/">Start your first run →</a></div></div><figure><img src="/assets/poke-survivor/original-title-1280.webp" srcset="/assets/poke-survivor/original-title-800.webp 800w, /assets/poke-survivor/original-title-1280.webp 1280w" sizes="(max-width:900px) 90vw, 48vw" width="1280" height="853" alt="Original PokéSurvivor title screen with pixel Pokémon on a dark grassy field"><figcaption>Original title screen, inspected October 26. © JPTER78 / respective rights holders; title-screen inspection, not a completed run.{r('entry')}</figcaption></figure></header>
<div class="ps-band"><div><small>Where</small><strong>Browser · PC &amp; mobile</strong></div><div><small>Entry</small><strong>Free fan project</strong></div><div><small>Progress</small><strong>Local &amp; cloud differ</strong></div><div><small>Checked</small><strong>October 26, 2026</strong></div></div>
<section class="section prose" id="identity"><p class="eyebrow">First, the right project</p><h2>PokeSurvivor is its own game.</h2><p>This section covers <strong>JPTER78’s PokéSurvivor at pokesurvivor.com</strong>. PokeBonk is Charcher’s different browser game; Megabonk is a different Steam game. Controls, accounts, partners and build recipes do not transfer between them.{r('readme')}</p><p><strong>Looking for Pokémon Survivor Burst?</strong> ClessioTV’s separate project has its own download and progression. Use {ext('https://eeveeexpo.com/threads/9705/page-2','ClessioTV’s Eevee Expo project page')}, rather than applying this browser guide to it.{r('burst')}</p><p id="editions">Other similar domains, including the Doofcraft address in search queries, are not established here as the author’s original edition. Its operator, build and save compatibility were not verified. Check the full address before signing in; this guide does not manage game accounts. Our <a href="{P}play/">Play page</a> loads a third-party edition from pokesurvivor.pro; its accounts, saves and rules must be checked separately.</p></section>
<section class="section" id="guides"><p class="eyebrow">Choose the task in front of you</p><h2>Your next useful answer.</h2><div class="ps-play-entry"><div><p class="eyebrow">Play / browser edition</p><h3>Jump into the forest.</h3><p>Click to load a playable third-party edition here. Start as a guest; keep original-game accounts and saves separate.</p></div><a class="button" href="{P}play/">▶ Play now</a></div>'''
    groups=[('start','01 / Start here','Learn the buttons, choose your entry and keep the language clear.',[
        ('beginners-guide/','First run','Only the active slot attacks; level-up choices and permanent upgrades do different jobs.'),('zh/beginners-guide/','中文入门攻略','原站、简繁中文设置、操作与升级卡对照。'),('es/mobile/','Español: jugar y descargar','Navegador, acceso instalado, HTML sin conexión y ports de terceros.')]),
        ('choices','02 / Build checks','Fix the assumptions before investing in a partner.',[('builds/','Physical, special & Bonds','Match the buff to your attack category and inspect the active group. This is a configuration guide, not a universal tier list.')]),
        ('progression','03 / Progression','Separate tickets, rift rewards and the 30-minute phase.',[('gacha/','Tickets & gacha','Check ordinary versus ×10 tickets and what a rarity guarantee actually promises.'),('rifts/','Rifts & Bonds','Read the eligibility window, random checks and the risk when returning.'),('arceus-judgment/','Judgment of Arceus','Survival and damage scoring are different goals after minute 30.')]),
        ('help','04 / Device, save & connection help','Pick the failure stage before changing settings or deleting anything.',[('mobile/','Mobile & download choices','Browser, installed shortcut, offline HTML and native ports have different boundaries.'),('save-and-sync/','Save & sync checks','Read the save state before changing devices; waiting is not cloud success.'),('multiplayer/','Friends & co-op rooms','Check nicknames, account readiness and the host before diagnosing a connection.'),('troubleshooting/','Loading, freezes & low FPS','Compare your symptom with dated reports and choose the next check.')])]
    for id,title,desc,cards in groups:
        home['body']+=f'<div class="ps-group" id="{id}"><h3>{title}</h3><p>{desc}</p><div class="guide-index">'+''.join(f'<a href="{P+slug}"><b>Field guide</b>{label}<span>{text}</span></a>' for slug,label,text in cards)+'</div></div>'
    home['body']+=f'''</section><section class="section prose" id="community"><h2>Get help from the right people.</h2><p>For game bugs, use {ext(G+'issues','JPTER78’s GitHub issue tracker')}. The {ext('https://www.reddit.com/r/pokesurvivor/','r/pokesurvivor player community')} is unofficial; a community link is not a promise of developer support. Include your game address, device, version and exact symptom. For an error in this guide, use our <a href="{P}contact/">contact page</a>.</p><p>The author’s {ext('https://jpter78.itch.io/pokesurvivor','itch.io release page')} lists the release as October 11, 2026. Its offline HTML instructions are different from the online account route.{r('itch')}</p><p class="note">This independent guide uses the creator’s public pages and a dated source snapshot. No full-run benchmark, physical-phone test or shared co-op test is claimed. A current menu and an older guide or port can disagree; use the edition named beside each answer.</p></section>'''

    begin('beginners-guide/','Poke Survivor Beginner Guide: Controls & First Run','Your first Poke Survivor run','Start Poke Survivor at the original game, learn active move slots and upgrade choices, and check what saves before you leave or switch devices.',diagram='run',alt=image_alt('Open original game','Move and switch','Choose one card','Check saved progress'),caption='Editorial route map: four separate decisions before the next run.')
    current['answer']='Open the original browser game, choose your Guest or account route, then pick a partner. Keep moving: the selected move attacks automatically. Learning four moves does not make all four fire together.'+r('guide')
    current['language']=f'<p class="language-switch">中文说明：<a href="{P}zh/beginners-guide/">PokeSurvivor 中文入门攻略</a></p>'
    s('entry','Start on the original website',f'<p>Use {ext("https://pokesurvivor.com/en/","pokesurvivor.com — original English entry")}. The author identifies this as the original website; a similarly named guide or hosted edition can have separate accounts and rules.{r("readme")}</p><ol><li>If you already have progress, return to the same address, browser profile and account first.</li><li>For a new visit, choose Guest for a short look or sign in/create an account on the game site. Do not treat Guest as a cloud account.</li><li>Follow the personality questions, then accept the suggested starter or choose another. The source lists 29 starting partners.</li><li>Before a longer attempt, inspect Controls and the save/account status. This guide does not manage the account.</li></ol>'+r('starters')+f'<p>The author’s downloadable HTML edition is solo with browser saves. If you want friends, cloud saves or leaderboards, the author directs players to the online game.{r("itch")}</p>')
    s('controls','Move, switch, pause',table(['Action','Keyboard','Touch / controller'],[('Move','WASD or arrows','Drag to move / stick or D-pad'),('Choose active move','1–4, or Q/E to cycle','Tap move / LB or RB'),('Use an orb','5–8','Tap orb / X; Y cycles orb'),('Pause','Esc','Pause button / Start')])+f'<p>These are creator-documented defaults; saved control settings take priority. On touch screens, begin in landscape. Test a slot change in clear space before doing it in a crowded wave.{r("guide")}</p><p><strong>A buff slot is not a damaging attack.</strong> If the field looks quiet after a switch, inspect the selected move before assuming the game froze. Bonds can join moves into one active slot; they are a separate progression system.</p>')
    s('cards','Read the offered card by what it changes',f'<p>Level-up choices can teach a move, improve a learned move, change a run stat or evolve an eligible move. A run-stat card is not a permanent upgrade for every later attempt.{r("level")}</p>'+table(['Immediate problem','Read this offer first','Why'],[('Low current HP','Sitrus Berry / Vigor','Berry heals 45% of maximum HP; Vigor adds 20 maximum HP and fills that added health in the checked source.'),('Main move is too weak','Upgrade the move you are actually using','Learning another unselected move does not automatically strengthen the active one.'),('Getting trapped','Movement or defense effect','Read the effect; extra damage and an escape route solve different problems.'),('Waiting for evolution','Required run-stat card','Permanent menu upgrades do not establish that this run’s condition is met.')])+ '<p>These are ways to read the choice, not a tested universal card order. In the checked source, once you already have two buff moves, further new buffs stop being offered. A full move/group layout is another reason not to expect every desired offer.</p>')
    s('evolution','Move evolution is not a species unlock',f'<p>For an eligible <strong>move</strong>, reach its maximum level, take its required run-stat card, then select the golden evolution card when offered. Read that move’s current requirement rather than assuming all attacks use the same stat.{r("moves")}{r("level")}</p><p>For example, the checked move definitions pair Ember’s evolution with Power and Quick Attack’s with Sprint. This does not mean the Pokémon species itself has permanently evolved or that its evolved species is now owned. Your collection, run moves and permanent partner upgrades are different records.</p><p>Use <a href="{P}builds/#groups">the Bond and active-group explanation</a> before expecting linked attacks to fire together. This page is not a new full evolution database.</p>')
    s('upgrades','Before spending coins on permanent upgrades',f'<p>Permanent improvements belong to the selected partner; a level-up card belongs to the current run. Confirm the partner name and the exact effect before spending. A later collected species is not automatically proof that an earlier partner’s upgrade spending moved with it.</p><p>Two separate feature requests ask for TM forgetting, and another asks for partner-upgrade resets. Requests are not evidence of an available refund. We have not verified an undo/refund route, so do not spend with the expectation of reversing it later.{r("i304")}{r("i348")}</p>')
    s('save','Finish by checking your save state',f'<p>Before closing or changing devices, inspect the original game’s Save result. Local progress, a pending cloud upload and confirmed cloud success are different states. The checked source does not upload Guest progress as an online account.{r("db")}</p><p>Keep the device with newer progress available if another device looks older. Follow <a href="{P}save-and-sync/">the save-state checklist</a> rather than clearing browser storage. That checklist does not promise to restore already lost data.</p>'+limit())
    links(('builds/','Check your active build'),('save-and-sync/','Keep local and cloud progress separate'),('mobile/','Choose a device route'))

    begin('save-and-sync/','Poke Survivor Save & Sync: Missing Progress Checks','Check your save before changing devices','Check Poke Survivor Guest, local and cloud states, understand pending saves, and follow dated cross-device reports without deleting newer progress.',diagram='save',alt=image_alt('Keep newer device','Read account and state','Save and wait','Confirm on other device'),caption='Preserve the newer session before comparing a second device.')
    current['answer']='Keep the device with your newest progress open and read its account and Save status first. “Waiting,” “offline” and a successful cloud save are different. This checklist cannot recover a deleted save or prove every missing-progress report has the same cause.'+r('db')
    s('status','Which save state are you looking at?',table(['State / route','What the checked source establishes','Next useful check'],[('Guest','Not a cloud account; saveNow returns a Guest failure','Do not assume changing device will carry it over.'),('Local / offline HTML','Browser-local storage, separate from cloud mode','Keep the same browser profile and game address.'),('Waiting / pending','An upload may be queued; success is not yet confirmed','Keep the session and connection; inspect the next status.'),('Offline / failed','Cloud success has not been confirmed','Restore connectivity and record the exact error.'),('Cloud success','That operation reports success','Then compare the account and collection on the other device.')])+f'<p>The implementation has separate modes and explicit return states; “the page still opens” does not establish that the server received the latest collection. We have not tested a live account transfer.{r("db")}{r("itch")}</p>')
    s('devices','A cautious order for two devices',f'<ol><li><strong>Identify the newer session.</strong> Note the Pokémon, upgrades and approximate balances visible there.</li><li><strong>Check the full domain and account.</strong> An independent hosted edition, offline copy or different browser account is not established as the same save.</li><li><strong>Finish the run normally where possible.</strong> Reloading is not a way to preserve an unfinished battle.</li><li><strong>Use Save and read the result.</strong> The checked implementation can queue a save because successful cloud writes have a minimum interval.</li><li><strong>Wait for actual success.</strong> Only then compare the same account on the other device. If it is still different, preserve the newer session and report both states.</li></ol><p>The source’s minimum interval is 65 seconds. A response telling you to wait does not mean the upload completed. It also does not mean every failure is solved by waiting exactly 65 seconds.{r("db")}</p>')
    s('reports','What players reported, and what it proves',f'<p>On October 24, SFtittto33 reported progress not syncing between browsers in issue #327. On October 25, NapiCornio independently reported a newer phone save than the PC save in #336.{r("i327")}{r("i336")}</p>'+table(['Report','Observed / reported action','Evidence limit'],[('#327 · cross-browser','Same account appeared to show different progress','Open at review; no recovery confirmed in the available thread.'),('#336 · phone / PC','Reporter said closing the other session, finishing a run and waiting before Save led to merged progress','One person’s successful report; not a blanket fix or permission to overwrite newer data.')])+ '<p>These are two distinct reports, not a measured failure rate. A source-code change and a closed issue are different from a successful transfer on your own devices.</p>')
    s('recovery','Login trouble is a separate branch',f'<p>The original login screen distinguishes an account linked to Google from an account without that link. If Google was already linked, use that same Google identity through the original website. Do not assume a new account or different email can recover the old one.{r("login")}{r("entry")}</p><p>Issue #331 describes a player who could no longer use the same name/password and had never linked Google. It remained an unresolved report in the reviewed material. This guide has no access to account records and cannot promise password or collection recovery.{r("i331")}</p>')
    s('preserve','Information to keep before asking for help','<ul><li>Game address and displayed version; device, browser and browser profile.</li><li>Whether you used Guest, local/offline or an online account.</li><li>Last visible newer collection and the exact Save message.</li><li>Which device is newer, and what changed before the discrepancy.</li></ul><p>Do not send passwords, cookies or account tokens. Do not clear site data as the first check: it can remove the local copy you still need.</p>'+limit())
    links(('multiplayer/','Check account readiness for co-op'),('mobile/','Keep browser and port saves separate'),('troubleshooting/','Choose another failure stage'))

    begin('builds/','Poke Survivor Builds: Physical, Special & Bonds','Check the build you actually have','Match Poke Survivor moves to physical or special buffs, understand active groups and Bonds, and compare five named partners without a fake tier list.',diagram='build',alt=image_alt('Move category','Matching buff','Active group','Spend with a plan'),caption='A build check starts with the selected move, not an overall stat rank.')
    current['answer']='Match the buff to the move’s damage category: Swords Dance boosts physical attacks; Nasty Plot boosts special attacks. Then check which group is active and which moves are linked by Bonds. A high overall stat does not make every move equally strong.'+r('moves')
    s('damage-type','Start from the attack, then choose the buff',table(['Damaging move category','Relevant partner field','Matching damage buff'],[('Physical','pa / physical attack multiplier','Swords Dance; Dragon Dance affects physical Attack too'),('Special','sa / special attack multiplier','Nasty Plot'),('Non-damaging buff','Read its own stat effect','Do not treat the buff itself as a damaging attack')])+f'<p>A move’s elemental type and physical/special category are separate. A Psychic-type partner does not make every learned move special, and the displayed <code>atk</code> field is the larger of pa/sa, not a universal damage multiplier for any move.{r("dex")}</p><p>For a Mewtwo using Psychic and Confusion, inspect their special category before copying a Swords Dance recommendation. The current source assigns the buff effects separately.</p>')
    s('old-videos','Why an older recommendation can mislead',f'<p>In a Reddit question read October 26, JeoYu asked why videos used Swords Dance with Mewtwo’s Psychic/Confusion. One visible commenter reported trying the buffs and seeing only Nasty Plot affect that setup; another explained that older versions lacked the split. Those are their reports, not our tests.{r("buffpost")}</p><p>Before following a clip, write down the game address, version and exact moves. If the clip predates a mechanics change or comes from a native port, copying the same four names is not enough. Use the current move category as the first check rather than treating view count as performance evidence.</p>')
    s('groups','Slots, active groups and Bonds',f'<ol><li><strong>Check the selected slot.</strong> Automatic attack normally uses the active move; unselected moves are not automatically simultaneous attacks.</li><li><strong>Read the slot contents.</strong> A Bond joins attacks into one slot/group, allowing those linked moves to act together.</li><li><strong>Count the Bonds you actually earned.</strong> A planned four-move group is not available just because all four moves are learned.</li><li><strong>Leave room for a damaging attack.</strong> Selecting an unlinked buff changes what is active; inspect the UI rather than assuming the whole loadout attacks.</li></ol><p>The reviewed level-up logic stops offering further new buff moves once you have two. That offer rule is separate from permanent upgrades, the number of ordinary slots and any particular recipe.{r("level")}{r("rift")}</p>')
    s('named-partners','Five named partners: read both attack sides',f'<p>These query-related examples are extracted from the checked game data. They are <strong>not ranked</strong> and require ownership; none is listed as a fresh starting partner. HP and speed are base game fields before your run cards, nature, ability, item and upgrades.{r("dex")}</p>'+table(['Partner','HP / speed','Physical pa / special sa','Useful check'],[('Mewtwo','118 / 133','1.31 / 1.55','Do not use its larger special value to score a physical move.'),('Eternatus','133 / 133','1.17 / 1.50','A strong special field is not proof that all Poison/Dragon moves work the same.'),('Keldeo','111 / 123','1.10 / 1.41','Inspect the category of the actual Water/Fighting move.'),('Kartana','97 / 124','1.70 / 1.02','Its large physical multiplier does not transfer to special attacks.'),('Slaking','138 / 120','1.58 / 1.22','Match the chosen move and buff rather than only reading the overall attack field.')])+ '<p>Method: select these five records by Pokédex ID from the creator’s G.DEX array and display pa and sa separately. There is no weighted score, simulated survival time, measured DPS or recommendation that this order is best. A full 966-partner strength ranking needs evidence beyond these fields.</p>')
    s('tm','Before teaching a TM or paying for a route',f'<p>The creator’s guide describes TMs as permanent teaching for eligible partners. Check the partner name, legal move and physical/special fit before applying one. A move being teachable does not establish that it solves the build’s current problem.{r("guide")}</p><p>Two different authors requested a way to forget an accidentally taught TM in issues #348 and #343. These are requests, not proof of an undo feature. We have not verified a refund or forgetting route; preserve that limitation before spending.{r("i348")}{r("i343")}</p><p>For run evolution, check the required card in the <a href="{P}beginners-guide/#evolution">upgrade explanation</a>. A permanent stat investment does not establish the run prerequisite.</p>'+limit())
    links(('rifts/','Earn and use a Bond'),('gacha/','Understand collection and tickets'),('beginners-guide/#cards','Read upgrade choices'))

    def mobile(slug,lang):
        es=lang=='es'
        begin(slug,'Poke Survivor: Descargar, Android, iPhone y Navegador' if es else 'Poke Survivor Mobile: Android, iPhone & Download',
              'Poke Survivor: jugar y descargar' if es else 'Poke Survivor on mobile',
              'Elige cómo jugar Poke Survivor: navegador, acceso instalado, HTML sin conexión o port nativo, con límites de guardado y problemas táctiles fechados.' if es else 'Choose the Poke Survivor browser, installed shortcut, offline HTML or native port, with save boundaries and dated touch-control reports.',
              diagram='mobile',alt='Browser / installed shortcut / offline HTML / third-party native port',caption='Cuatro rutas; sus cuentas y guardados no son intercambiables.' if es else 'Four access routes; a similar name does not establish shared saves.',lang=lang)
        current['answer']=('Para el juego original, abre pokesurvivor.com en el navegador. No necesitas un APK para esa ruta. Un acceso instalado, la copia HTML sin conexión y el port nativo de terceros son opciones distintas; comprueba su guardado antes de cambiar.' if es else 'Start with pokesurvivor.com in your phone’s browser. That route needs no APK. An installed web shortcut, the author’s offline HTML copy and a third-party native port are different choices; check the save boundary before switching.')+r('guide')
        current['language']=f'<p class="language-switch"><a href="{P+("mobile/" if es else "es/mobile/")}">{"English: mobile and download choices" if es else "Español: jugar y descargar"}</a></p>'
        s('browser','Empieza por el navegador original' if es else 'Start at the original browser game',f'<p>{ext("https://pokesurvivor.com/en/","pokesurvivor.com — juego original" if es else "pokesurvivor.com — original game")}</p>'+('<ol><li>Usa el mismo perfil del navegador si ya tienes progreso.</li><li>Prueba en horizontal y comprueba el movimiento táctil antes de una partida larga.</li><li>Abre Ajustes y revisa Controles; los botones guardados pueden cambiar la distribución.</li><li>Comprueba la cuenta y el estado de Guardar antes de cambiar de dispositivo.</li></ol><p>La guía del creador describe controles táctiles y mando. Esto no demuestra que todos los teléfonos funcionen bien ni garantiza FPS. No hemos probado un iPhone o Android físico.</p>' if es else '<ol><li>Keep the same browser profile if it holds your progress.</li><li>Start in landscape and check movement before a longer run.</li><li>Inspect Settings → Controls; saved layouts may differ from defaults.</li><li>Check the account and Save state before moving to another device.</li></ol><p>The creator documents touch and controller support. That establishes available controls, not smooth performance on every phone. No physical-phone test or FPS benchmark is claimed.</p>')+r('guide'))
        s('ports','Qué estás descargando o instalando' if es else 'Which route are you choosing?',table(['Ruta' if es else 'Route','Qué es' if es else 'What it is','Límite importante' if es else 'Important boundary'],[
            ('Navegador original' if es else 'Original browser','pokesurvivor.com','Cuenta y guardado del original; revisa Guardar.' if es else 'Original account route; inspect Save status.'),
            ('Acceso web instalado' if es else 'Installed web shortcut','Añadir a pantalla de inicio / instalar desde el navegador' if es else 'Add to Home Screen / browser install','No es por eso un APK nativo ni una garantía de modo offline.' if es else 'Not automatically a native APK or proof of offline support.'),
            ('HTML offline del autor' if es else 'Author’s offline HTML','Instrucciones en itch.io: descomprimir y abrir index.html' if es else 'Author’s itch instructions: unzip and open index.html','Solo, guardado en navegador; online para nube, cooperación y ranking.' if es else 'Solo, browser saves; online route for cloud, co-op and rankings.'),
            ('Port nativo de terceros' if es else 'Third-party native port','JayElDragon Poke Survivors V5.1','Otra versión y reglas; no se ha confirmado transferencia de tu cuenta original.' if es else 'Separate build/rules; original account transfer not established.')])+f'<p>{ext("https://jpter78.itch.io/pokesurvivor","JPTER78 en itch.io — instrucciones HTML" if es else "JPTER78 on itch.io — offline HTML instructions")} · {ext("https://github.com/JayElDragon/poke-survivor/releases/tag/V5.1","JayElDragon en GitHub — V5.1" if es else "JayElDragon GitHub — V5.1 release")}.{r("itch")}{r("port")}</p>'+('<p>El port V5.1 anuncia cambios en Tower, fusiones y Arceus: no copies esos límites al juego web original. No hemos instalado sus ejecutables ni probado migración de partidas.</p>' if es else '<p>The V5.1 port release describes different Tower, fusion and Arceus rules. Do not apply its endgame rewards or run duration to the original browser game. We did not install its executables or test save migration.</p>'))
        s('controls','Movimiento, ataques y mando' if es else 'Separate movement, slots and controller input',('<p>Arrastra para moverte; toca un movimiento para activarlo. Atacar automáticamente no significa que todos los movimientos se lancen a la vez. En mando, el creador documenta stick/cruceta, LB/RB para cambiar movimientos y Start para pausar. Comprueba lo que detectan tu navegador y Ajustes antes de iniciar.</p><p>Si falla un botón táctil pero el menú responde, anota la zona y orientación; si también se para el reloj, es otra rama de diagnóstico. Cambiar de navegador sin comprobar el guardado puede ocultar la copia que aún conservas.</p>' if es else '<p>Drag to move and tap a move to make it active. Automatic attack does not mean every learned move fires at once. The creator documents stick/D-pad movement, LB/RB slot cycling and Start to pause on a connected controller. First check what your browser and Controls screen actually detect.</p><p>If only a touch region fails while menus still respond, note its position and orientation. If the clock also stops, use the general freeze checklist instead. Switching browser profiles before checking saves can hide the local copy you still have.</p>')+r('guide'))
        s('joystick','Informes táctiles y de instalación' if es else 'Dated touch and installation reports',('<p>El issue #337, abierto por g4to12 el 25 de octubre, describe un joystick que deja de responder. Dos usuarios distintos lo corroboraron el 26; #341 es otro informe de movimiento móvil. No hay una solución universal verificada aquí.</p>' if es else '<p>In issue #337, opened October 25, g4to12 reported the joystick stopping. Two other commenters corroborated on October 26; issue #341 is another mobile movement report. This is a cluster of reports, not a tested universal fix.</p>')+r('i337')+r('i341')+('<p>DrAstroLR informó el 26 de octubre de una app web instalada en HyperOS que no abría, y dijo que volver al sitio y usar la acción de instalar la abría. Es el método de una persona; no demuestra que debas borrar datos ni reinstalar.</p>' if es else '<p>On October 26, DrAstroLR reported a Chrome-installed web app failing to launch on HyperOS, and described opening the website and using its install action to launch the existing installation. This is one person’s workaround; it does not establish that deleting data or reinstalling is needed.</p>')+r('i349'))
        s('next','Qué comprobar después' if es else 'Choose the next check',('<ul><li>Controles: revisa distribución, orientación y acción exacta.</li><li>Guardado: conserva el dispositivo con más progreso y lee el estado de Guardar.</li><li>Rendimiento: anota el momento y los ajustes; no asumas que bajar gráficos corrige un bloqueo del joystick.</li><li>Reporte: indica dirección del juego, versión, navegador y síntoma; no envíes contraseñas.</li></ul><p class="note">Revisión de fuentes del 26 de octubre de 2026, snapshot 680c3e12c670. No se han probado teléfonos físicos, APK, transferencia ni rendimiento. Los informes abiertos pueden cambiar con un parche.</p>' if es else '<ul><li><strong>Input:</strong> inspect the layout, orientation and exact unresponsive action.</li><li><strong>Save:</strong> preserve the newer device and read the Save result.</li><li><strong>Performance:</strong> record when it slows and the current settings; lower graphics is not a proven joystick fix.</li><li><strong>Report:</strong> include address, build, browser and symptom, not passwords.</li></ul>'+limit()))
        links(('save-and-sync/','Save and sync checks'),('troubleshooting/','Freeze and performance checklist'),('beginners-guide/','Controls and first-run decisions'))
    mobile('mobile/','en');mobile('es/mobile/','es')

    begin('multiplayer/','Poke Survivor Multiplayer: Friends, Rooms & Co-op','Join friends, then check the connection','Set up Poke Survivor friends and co-op rooms, check nickname and account readiness, and separate joining failures from dated in-run lag reports.',diagram='coop',alt=image_alt('Original site and account','Nickname and friend','Room and host','In-run connection'),caption='Joining a friend and keeping a running room connected are different stages.')
    current['answer']='Use the original online game and an online account, add your friend by their public nickname, then invite them to a room. If it fails, first identify whether the problem is finding the friend, joining the room or staying connected during play.'+r('guide')+r('social')
    s('join','Before pressing Start',f'<ol><li>Both players open the same original game address. A port or another hosted edition is not established as compatible.</li><li>Check that online account services are available; Guest/offline HTML is not the same online route.</li><li>Compare the public nickname shown in the game. Do not send passwords or assume an email address is the friend-search identifier.</li><li>Add the friend, send the room invitation and confirm both players reached the room before the host starts.</li><li>If one player is still on a menu, resolve that state before treating it as mid-run lag.</li></ol><p>The creator describes up to four-player co-op, shared experience and reviving a downed teammate by standing nearby. This guide has not completed a shared match or timed a revive.{r("guide")}{r("social")}</p>')
    s('connection','Follow the failure stage',table(['Where it fails','Check first','What not to infer'],[('Friend not found','Public nickname, correct account and same game domain','A matching display name in another edition is not proof it exists on this server.'),('Invitation / room entry','Both accounts online; both at the correct menu and version','Deleting an account is not a connection repair.'),('Room starts but one player stays behind','What the host and guest each see; current build','A loaded menu is not a successful shared run.'),('Lag after several minutes','Which device is host, current network and exact time/symptom','Solo performance does not establish co-op performance.'),('Host disappears','Whether the room reports disconnect/closure','Automatic host migration is not established here.')])+f'<p>The checked implementation makes the host authoritative for enemies, team experience and the clock; each player controls their own partner state. That division helps describe a report, but does not identify your network fault by itself.{r("coop")}</p>')
    s('reports','Recent original-project reports',f'<p>sukyozumaru reported a friend nickname appearing nonexistent on October 25 (#333). LosMeia and KaonHew02 separately reported co-op lag on October 24 and 23 (#325/#306). These are different symptom records, not proof that all co-op is broken or that all players need the same fix.{r("i333")}{r("i325")}{r("i306")}</p><p>First compare game address, account readiness and version. Changing the host can be a comparison check if both players can save and return safely; it is not a verified cure. Keep notes on whether the failure follows a device, a host or a specific room.</p>')
    s('network','Direct connections and server availability',f'<p>The source describes peer connections and alternate network paths, but their availability depends on the current published configuration and server. Do not assume a relay is active simply because a related source file mentions it. This review did not inspect private server configuration or complete a network-failure test.{r("coop")}</p><p>A short interruption, a closed room and a lost host are different events. Preserve the displayed message and what the other player sees. Do not claim the run will survive a host exit or that it will resume after any reconnect.</p>')
    s('record','A useful report has two sides','<p>Record the host and guest devices/browsers, game addresses and versions, nicknames needed to identify the room, which menu each player reached, the time the failure began, and whether enemies, movement and the clock still update. Omit passwords, tokens and private account data.</p>'+limit())
    links(('save-and-sync/','Save before changing device or host'),('mobile/','Separate input problems'),('troubleshooting/','Describe the failure stage'))

    begin('gacha/','Poke Survivor Gacha: Tickets, Buttons & Pity','Check tickets before choosing a pull','Understand Poke Survivor ticket types, four pull costs and banner pity, then compare dated reports of disabled gacha and ticket-amount confusion.',diagram='gacha',alt=image_alt('Choose ticket type','Choose banner','Check button cost','Read rarity guarantee'),caption='A ×10 ticket balance and an ordinary ticket balance are different counters.')
    current['answer']='A ten-pull needs 10 ordinary tickets or one ×10 ticket; a hundred-pull needs 100 ordinary tickets or ten ×10 tickets. Check the selected button and balance first. A rarity guarantee does not guarantee the particular Pokémon you want.'+r('gacha')
    s('costs','Four buttons, four eligibility checks',table(['Chosen pull','Ordinary-ticket button','×10-ticket button'],[('10 results','10 ordinary tickets','1 ×10 ticket'),('100 results','100 ordinary tickets','10 ×10 tickets')])+f'<p>These costs are read from <code>costOf</code> and the matching interface buttons, not inferred from an icon. The two balances are checked separately: do not add “4 ordinary + 1 ×10” and assume any button accepts that combined total.{r("gachaui")}</p><p><strong>Worked checks:</strong> 9 ordinary tickets alone do not qualify for the ordinary ten-pull button. One ×10 ticket qualifies for its ten-pull button, not for the hundred-pull button. Ten ×10 tickets meet the latter cost. This arithmetic establishes source-defined eligibility, not that every reported disabled button is user error.</p>')
    s('pity','What the guarantees do and do not promise',f'<p>The checked source has separate pity per regional banner. A ten-pull guarantees at least an Epic-or-better result; the five-star counter governs rarity, not a named species. In the checked pull loop, the counter increments first and requests five-star rarity when it reaches 70. That is the 70th pull since the last five-star if none appeared earlier, not a promise about a particular species. The source comment’s “next pull” wording is less precise than this executable condition.{r("gacha")}</p><p>Switching region does not mean one shared global pity counter. A five-star result is not proof it must be shiny, and a shiny roll is separate from rarity. A hundred-pull is handled as ten ten-pull batches in the reviewed code; it is not a new guarantee of a specific legendary.</p>')
    s('reports','When the balance and result seem wrong',f'<p>FeujKiller reported having tickets but being unable to use gacha on October 25 (#335); erenlim0521-hue reported an apparent ×10 amount mismatch the same day (#334). Neither report alone establishes a root cause. On October 23, EremFP asked about not receiving Sandslash after many pulls (#314); that is a desired-species question, not a controlled drop-rate experiment.{r("i335")}{r("i334")}{r("i314")}</p>'+table(['Symptom','Useful next check','Evidence boundary'],[('Button unavailable','Record each ticket balance and which button is disabled','Correct source cost does not rule out a UI or account bug.'),('×10 reward looks short','Compare the two balances and exact reward message','Do not relabel a real report as mere confusion without the before/after values.'),('Wanted species still missing','Check the banner and distinguish rarity from species selection','Many failed pulls do not create a guarantee of that species.')]))
    s('earn','Use earned tickets in the right edition',f'<p>The original creator describes tickets as earned through play, not bought for money. Regular enemies and bosses/rift rewards can contribute tickets; exact reward events are not a guaranteed farming rate. The game’s original guide and itch release both describe this free-play boundary.{r("guide")}{r("itch")}</p><p>A similarly named edition offering ticket packs is not established as this original project. Check the address and save system before following its prices, banners or account instructions. This guide offers no ticket sales, codes or purchase buttons.</p>')
    s('after','Before leaving after a pull',f'<p>Inspect the collection and Save state on the current device before expecting the result on another one. If the new partner is missing elsewhere, follow <a href="{P}save-and-sync/">save and sync checks</a>; repeated pulls do not diagnose an upload problem.</p>'+limit('No live gacha pull, shiny test or probability simulation was performed.'))
    links(('rifts/','Rift rewards and Bonds'),('builds/#named-partners','Read a partner’s physical and special fields'),('save-and-sync/','Check collection sync'))

    begin('rifts/','Poke Survivor Rifts: Timing, Rewards & Return Checks','Read the rift window before waiting','Check Poke Survivor rift eligibility, random attempts, portal and arena timers, Bond rewards and the risk when returning to the main map.',diagram='rift',alt=image_alt('Eligible map window','Random check','Enter timed arena','Return and inspect group'),caption='Eligible attempts are not a wall-clock promise that a portal must appear.')
    current['answer']='Rifts need an eligible map state before their random opening checks run. Enter an opened portal before it expires, then finish the timed arena for its reward and Bond. If no rift appears, inspect the run stage and boss state before assuming a fixed timer failed.'+r('rift')
    s('spawn','Why a rift may not have opened yet',f'<p>The checked code begins eligible checks only after the early-run threshold and stops new openings two minutes before the 30-minute Judgment phase. Existing arenas, host authority in co-op and a living scheduled boss also affect when an attempt can occur.{r("rift")}{r("judgment")}</p>'+table(['Source condition','What to do with it'],[('Before the early threshold','Continue the run; a rift is not promised immediately at spawn.'),('A scheduled boss is alive','Resolve that state before counting missed eligible checks.'),('Already in an arena / existing portal','Do not expect another independent opening simultaneously.'),('At or beyond 28:00','New rifts stop opening before the Judgment boundary.'),('Co-op guest','The authoritative opening decision belongs to the host.')])+ '<p>Constants in the source include a 75-second early boundary, 30-second eligible checks and a base 20% chance that increases after misses. Because checks pause or skip under conditions, “a maximum of five checks” is not an unconditional two-and-a-half-minute wall-clock guarantee. Do not infer a kill-count trigger from that timer alone.</p>')
    s('timers','Portal time and arena time are different',f'<p>An opened portal has a 45-second lifetime in the checked code. The legendary arena has its own 120-second limit after entry. Spending time fighting a scheduled boss before an opening is a different wait from these two countdowns.{r("rift")}</p><ol><li>Notice the portal and read the current field situation.</li><li>Enter before its portal lifetime expires if you choose that fight.</li><li>In the arena, track its own fight timer and attack warnings.</li><li>After the result, inspect your active group and return position instead of assuming a safe pause on the original map.</li></ol><p>These are source-defined timers, not observed average spawn times or a promise that a particular legendary will appear.</p>')
    s('rewards','A Bond changes your grouping options',f'<p>A won rift increments a Bond and offers the grouping step. Linking moves lets them share one active slot; owning four unlinked moves is a different setup. Read the group you return with before the next wave.{r("rift")}</p><p>The creator documents tickets/coins as arena rewards, while the source distinguishes ordinary rifts from Judgment legendaries. Do not use the latter as an assumed source of the same rewards. A win does not establish that you now own the legendary species as a selectable partner.{r("guide")}{r("judgment")}</p>')
    s('return','Returning is a risk check, not a guaranteed safe spot',f'<p>bmorman reported being hit immediately after returning from a rift on October 23 (#312). That is one original-project report, not a reproduction by this site or proof that every return is unavoidable.{r("i312")}</p><p>The checked return path restores the map state and player position, clears several temporary effects and can offer the Bond step. It does not justify a universal promise of a safe empty radius. On return, read the field, your health and the selected group; if the same symptom recurs, include the return location and version in the report.{r("rift")}</p>')
    s('next','At the end of the rift window',f'<p>If your next goal is a Bond, waiting for a new portal after 28:00 is the wrong plan for the checked version. If the run reaches 30:00 while you are inside an arena or choosing a card, the Judgment transition waits for that state to finish. Read the <a href="{P}arceus-judgment/">Judgment timeline</a> before applying an older infinite-run strategy.{r("judgment")}</p>'+limit())
    links(('builds/#groups','Use the Bond in an active group'),('gacha/','Keep ticket types separate'),('arceus-judgment/','Prepare for the 30-minute phase'))

    begin('arceus-judgment/','Poke Survivor Arceus: Judgment & Minute 30 Checks','Survival and damage after minute 30','Understand Poke Survivor Judgment at minute 30, separate survival and damage goals, and check the 28-minute rift and 35-minute item boundaries.',diagram='arceus',alt=image_alt('28:00 no new rifts','30:00 Judgment','Survival or damage goal','35:00 held item breaks'),caption='Timeline from the checked original-project source; ports can change these rules.')
    current['answer']='At minute 30, the original game enters Judgment of Arceus. Hitting Arceus for a damage score is different from defeating it. Choose whether you are pursuing survival time or damage, and recheck old advice that assumes endless rifts, doubled legendary scaling or a permanent held item.'+r('judgment')
    s('timeline','Three boundaries that change the plan',table(['Run time','Checked rule','Practical consequence'],[('28:00','New rifts stop opening','Do not wait for another portal as your remaining Bond plan.'),('30:00','Judgment transition; waits for an active arena/card choice to finish','Finishing the current choice is different from avoiding the phase.'),('35:00','Arceus breaks held items, including Focus Sash','A held-item-dependent plan is not permanent protection.')])+f'<p>These boundaries come from the fixed source. We have not completed a run through them. A native port can explicitly change the Arceus outcome or rewards, so identify the edition first.{r("judgment")}</p>')
    s('goals','Pick the score you are trying to improve',f'<p>The source tracks damage dealt to Arceus separately from survival. It allows attacks to register damage for scoring while Arceus remains invincible in this encounter. “You can hit it” must not become “you can kill it for a reward.”{r("judgment")}</p>'+table(['Goal','Read before changing the build','Limit'],[('Survive longer','Movement soft cap, contact damage, item break and incoming warnings','More speed on the ordinary map does not scale identically in Judgment.'),('Deal more damage','Current Plate/type, actual physical/special fit and target selection','Base attack alone does not establish a best damage build.'),('Beat new legendaries','Their increasing HP/damage and the time they enter','Judgment legendaries do not carry the normal rift reward assumptions.')])+ '<p>This is a plan-reading method, not a tested strongest route. Keep the goal and the same-version conditions with any run comparison.</p>')
    s('changes','Why older clips and guides can disagree',f'<p>The checked implementation adds a legendary every five seconds and uses successive HP ×1.25 and damage ×1.15, rather than the older doubling description. It applies a movement-speed soft cap and later increases contact danger. The source also reduces the damage registered on Arceus; a raw move number is not your final score.{r("judgment")}</p><p>Read each rule at its own scope. A main-map poison or burn strategy cannot be assumed to keep the same boss-health scaling in Judgment, and a port that says Arceus can be defeated is describing different code.</p>')
    s('reports','What the player question actually asks',f'<p>Daraen41 asked why a run that had previously lasted much longer suddenly entered the “hold out” Arceus phase at half an hour. Visible replies discuss very different survival times and setups. Those reports establish confusion about the phase, not a validated best build or an average survival target.{r("arceuspost")}</p><p>DylanZM separately reported FPS dropping when Arceus appears in original-project issue #347 on October 26. If the problem is frame rate or frozen input, use <a href="{P}troubleshooting/">the symptom checklist</a> rather than assuming a change of Pokémon solves it.{r("i347")}</p>')
    s('limits','Before claiming a route works','<ul><li>Record the exact game address/version and whether the run is solo or co-op.</li><li>Keep permanent upgrades, nature/ability and held item with the move list.</li><li>Separate time survived from damage scored; keep the selected Plate/type if comparing damage.</li><li>Do not label a theorycraft, source reading or another player’s clip as this site’s completed run.</li></ul>'+limit('No infinite-survival, kill or high-score guarantee is made.'))
    links(('rifts/#next','The last rift window'),('builds/','Check physical and special assumptions'),('troubleshooting/','Separate FPS from combat difficulty'))

    begin('troubleshooting/','Poke Survivor Not Working: Freeze & FPS Checks','Find the failure stage first','Separate Poke Survivor loading, input, clock freezes and low FPS using dated original-project reports, with cautious checks and clear reporting limits.',diagram='help',alt=image_alt('Loading?','Input or clock?','FPS or network?','Record exact report'),caption='A symptom map, not a claim that different bugs share one repair.')
    current['answer']='Identify what stopped: loading, one input, the run clock, frame rate, saving or the co-op connection. Preserve existing progress before refreshing or clearing anything. The dated reports below help narrow the next check; they are not universal fixes.'
    s('triage','Choose the branch that matches your screen',table(['What you can still see/do','Next check','Use this detailed guide'],[('Blank or loading screen','Try the original game in its own tab; record address and browser','Device/access route below'),('Menus work, movement fails','Check input layout/orientation and whether the clock continues',f'<a href="{P}mobile/#joystick">Mobile input reports</a>'),('Grass/animation moves but clock and inputs stop','Record time, selected upgrade and exact screen; do not assume ordinary lag','Clock-freeze report below'),('Clock continues but everything is slow','Record settings, device, viewport and run stage','FPS / viewport reports below'),('Only other players lag','Record host/guest states and room stage',f'<a href="{P}multiplayer/">Co-op checks</a>'),('Collection differs or Save fails','Keep the newer session and read Save state',f'<a href="{P}save-and-sync/">Save and sync</a>')])+f'<p>The original browser route is {ext("https://pokesurvivor.com/en/","pokesurvivor.com")}. Offline HTML and third-party native ports are different targets for a bug report.{r("entry")}{r("itch")}</p>')
    s('reports','Dated reports from the original project',f'<h3>Extreme viewport: enemies appear to stop</h3><p>bbbbbb123 reported enemy recycling outside the visible area at a very unusual 1587×188 window on October 26 (#350), with a source-based diagnosis. If your window is similarly extreme, return it to a conventional aspect ratio and compare what changes. This is a targeted check, not proof that all missing enemies have this cause; we did not reproduce the report.{r("i350")}</p><h3>Visual animation continues, run clock stops</h3><p>turbo012 reported a stopped clock and unresponsive inputs while some grass/water animation still moved on October 23 (#318). Record that distinction: moving visual effects alone do not prove the run is advancing. The report did not establish a universal repair.{r("i318")}</p><h3>Low FPS when Arceus appears</h3><p>DylanZM reported this on October 26 (#347). Note whether the clock continues and what happens before/after the transition. A demanding scene is a different symptom from a completely stopped simulation.{r("i347")}</p>')
    s('settings','Change one thing, preserve the comparison',f'<ol><li>Note the game address, displayed version and exact stage.</li><li>Check the game’s current graphics/control settings; change one option at a time so the comparison means something.</li><li>If the viewport is extremely wide or short, try an ordinary shape.</li><li>If only touch input fails, follow that symptom branch rather than assuming graphics settings repair it.</li><li>Before any reload, inspect Save and acknowledge that an unfinished battle is not guaranteed to resume.</li></ol><p>The creator documents settings and supported input routes, but that is not a minimum-device specification, measured FPS promise or diagnosis of your device.{r("guide")}</p>')
    s('report','What to include in an actionable report',f'<p>Use {ext(G+"issues","JPTER78’s GitHub issue tracker")} for the original game. Include the full game address, version, device/OS/browser, viewport or orientation, run time, selected partner/move, actions immediately before failure, and whether menus, clock, audio and visual animation still work. If relevant, identify host versus guest.</p><p>Say which checks changed the symptom and which did not. Include no passwords, cookies or account tokens. A report remaining open means its outcome was not established here; it is not evidence of a measured global failure rate.</p>'+limit())
    links(('save-and-sync/','Preserve the newer progress'),('mobile/','Check touch and install routes'),('multiplayer/','Separate room and network stages'))

    begin('zh/beginners-guide/','Poke Survivor 中文攻略：操作、升级与存档','Poke Survivor 中文入门攻略','认准原站，设置简体或繁体中文，分清主动招式、局内升级卡与永久培养，并在离开前检查存档状态。',diagram='run',alt='打开原站 → 移动切招 → 读取升级卡 → 检查存档',caption='操作示意图；不是本站通关或真机测试画面。',lang='zh-Hans')
    current['answer']='先打开 JPTER78 的 pokesurvivor.com，选访客或账号入口，再确认伙伴。移动负责躲避，当前选中的招式自动攻击；学会四个招式不代表四招同时释放。离开或换设备前，要检查保存状态。'+r('guide')
    current['language']=f'<p class="language-switch"><a href="{P}beginners-guide/">English beginner guide</a></p>'
    s('language','游戏本身已提供简体与繁体中文',f'<p>本次核对的原站语言脚本明确列出简体中文、繁體中文。优先使用已经保存的语言设置；没有保存设置时，<code>/en/</code> 路径优先显示英文，再根据浏览器语言选择。zh-TW/zh-HK/zh-MO对应繁体，其余中文识别通常对应简体。需要中文时，先在游戏设置中检查语言，不必先安装第三方汉化脚本。{r("locale")}</p><p>旧攻略里“只有英文和西班牙文”的说法不能直接套用本次版本。本文查阅了原作者简繁词典；不声称已经在实体手机上验证全部中文界面。{r("zh")}{r("hant")}</p>')
    s('start','认准项目，再开始第一局',f'<p>原作者入口：{ext("https://pokesurvivor.com/","pokesurvivor.com 原站")}。PokeBonk 是另一款游戏；Pokémon Survivor Burst 和第三方原生端口也有各自规则。不要把它们的账号、联赛或进化表混用。{r("readme")}</p><ol><li>已有进度时先回到原来的网址、浏览器资料和账号。</li><li>首次进入，访客适合短暂查看；不要把访客当成云端账号。</li><li>按性格问题得到初始伙伴建议，不合适可以选择另一个。源码列出29个初始伙伴。</li><li>开始前先看控制设置和存档状态，不急着复制最强配装。</li></ol>'+r('starters'))
    s('controls','只需要先记住这些操作',table(['操作','键盘','触屏/手柄'],[('移动','WASD 或方向键','拖动移动 / 摇杆或方向键'),('选择主动招式','1–4；Q/E循环','点击招式 / LB、RB'),('使用宝珠','5–8','点击宝珠 / X使用、Y切换'),('暂停','Esc','暂停按钮 / Start')])+f'<p>以上为作者指南记录的默认操作，已保存的自定义设置优先。手机先横屏检查按钮位置；四个招式槽并不默认一起输出，Bond（羁绊）才会改变同一主动组里同时发动的招式。{r("guide")}</p>')
    s('cards','把卡片原名与用途一起读',table(['卡片/概念','先理解什么','适用判断'],[('Vigor / 活力','最大HP增加20，并补满新增部分','与立即按比例回血不是同一种效果'),('Power / 威力','本局伤害增益','仍要看你当前正在用什么招式'),('Sprint / 奔跑','本局移动速度','帮助移动，不是永久速度培养'),('Reflexes / 反应','招式冷却缩短','与学一个新招式不同'),('Sitrus Berry','立即回复最大HP的45%','当前血量危险时读清即时效果'),('New move / Move upgrade','新招式 / 已有招式升级','新学的未选中招式不一定正在攻击')])+f'<p>英文名保留作对照，实际中文以游戏当前词典为准。局内卡片不会自动变成伙伴永久培养；先读效果，再按当前问题选，不把这张表当通用升级顺序。{r("level")}{r("zh")}</p>')
    s('partners','超梦与纸御剑：先分物理、特殊',f'<p>查询中出现超梦（Mewtwo）、无极汰那（Eternatus）、凯路迪欧（Keldeo）、纸御剑（Kartana）与请假王（Slaking），不等于它们都是新手免费初始伙伴或有相同获取方式。</p><p>以源码字段为例，Mewtwo物理/特殊倍率分别为1.31/1.55，Kartana为1.70/1.02。用两者较大值当所有招式的倍率，会误判配装。这些字段不含完整招式、特性、道具和实际走位，不能直接推出综合最强榜。{r("dex")}</p><p>先看攻击是物理还是特殊，再配Swords Dance或Nasty Plot；完整五角色对照见<a href="{P}builds/#named-partners">英文构筑核对表</a>，不是全角色强度排名。{r("moves")}</p>')
    s('evolution','招式进化、物种收藏、永久升级要分开',f'<p>可进化招式需要本局达到其等级和属性卡条件，再选择金色进化卡。例如Ember与Power、Quick Attack与Sprint的配对来自本次源码定义。菜单里买过永久升级，不等于本局已经拿到那张属性卡。{r("moves")}{r("level")}</p><p>这也不能证明伙伴物种永久进化或已经解锁对应收藏。误学TM或伙伴培养退款目前没有本文核验过的逆转流程；功能请求不能当现成功能。花费前检查伙伴和招式对象。{r("i348")}</p>')
    s('save','结束前检查：本地保存不等于云端成功',f'<p>访客、离线HTML、本地账号与在线云存档不是同一条路径。源码会区分等待、离线、失败和成功；显示等待时不要马上换设备，认为新伙伴已经上传。保留进度较新的设备和会话，先核对网址与同一账号。{r("db")}</p><p>第#331号原始问题记录了未绑定Google时用户名/密码无法登录的情况；这里不能承诺恢复账号或找回已丢失收藏。不要把新建账号当恢复步骤。{r("i331")}</p><p class="note">2026-10-26核对；规则以原项目源码680c3e12c670和作者页面为依据，属于单作者来源。本站没有完成整局、多人、真机或存档恢复测试。其他版本可能不同。</p>')
    links(('save-and-sync/','存档状态与换设备核对（英文）'),('builds/','物理/特殊与连结构筑（英文）'),('mobile/','手机与下载路线（英文）'))

    # The old site has no generally applicable About/Contact; the PokeBonk
    # notices are explicitly section-scoped. These are necessary support pages.
    begin('about/','About the Poke Survivor Guide | Megabonk.org','About these guides','How Megabonk.org maintains independent PokéSurvivor guides, checks creator sources and dated player reports, and labels material and test limitations.',diagram=None,kind='trust')
    current['body']=f'<p>This is the PokéSurvivor guide section of Megabonk.org, maintained by this website’s independent publisher. We help readers identify JPTER78’s browser game and make practical choices about controls, moves, tickets, devices, saves and co-op.</p><h2>Our method</h2><p>Guides use the creator’s public pages, fixed source revisions and dated original player reports. Creator pages and source files are one author’s evidence, not independent double confirmation. Data transformations explain their method and avoid presenting base-stat fields as measured win rates.</p><p>The October 26 review uses snapshot 680c3e12c670. A title-screen inspection is recorded separately from play. We did not complete controlled runs, physical-phone benchmarks, multiplayer sessions or account recovery. Advice keeps those limits beside the relevant claim.</p><h2>Separate projects and rights</h2><p>This website is not run by Jonathan Piera Torregrosa (JPTER78), Nintendo, Creatures, GAME FREAK or The Pokémon Company. PokeBonk and Megabonk have separate facts and guides. Game images and names belong to their respective rights holders. Our beacon/keyway mark identifies this guide, not the game.</p><h2>Corrections</h2><p>Use <a href="{P}contact/">the contact page</a> with the guide URL, game edition and supporting source. We can correct this website; we cannot change the game or access player accounts. <a href="{P}privacy/">Our privacy notice</a> explains website services.</p>'
    begin('contact/','Contact the Poke Survivor Guide | Megabonk.org','Contact the guide publisher','Send a correction or rights request about the independent Poke Survivor guides on Megabonk.org, or find the original game’s separate bug-report route.',diagram=None,kind='trust')
    current['body']=f'<p>For a factual correction, broken link or rights request concerning this guide, email {ext("mailto:qsyhxw@gmail.com?subject=%5BMegabonk.org%5D%20Website%20feedback","qsyhxw@gmail.com")}.</p><h2>Make the correction easy to check</h2><p>Include the page URL, the statement or image in question, the full game address/version and a source supporting the change. Do not send game passwords, account tokens, cookies or unnecessary personal information. We do not promise a response time.</p><h2>Game bugs and account trouble</h2><p>This guide publisher does not operate game servers or recover accounts. For JPTER78’s original game, use {ext(G+"issues","JPTER78’s GitHub issue tracker")}. State the symptom, device/browser and game edition. Other ports and hosted editions have their own maintainers.</p><h2>About the website</h2><p>Read <a href="{P}about/">our source and editorial method</a> or <a href="{P}privacy/">our privacy notice</a> before sending personal details.</p>'
    begin('privacy/','Poke Survivor Guide Privacy | Megabonk.org','Privacy notice','Privacy practices for the Poke Survivor guide section: Cloudflare hosting, Google AdSense, email contact and links to separate external game services.',diagram=None,kind='trust')
    current['body']=f'<p>This notice covers the independent guides at megabonk.org/poke-survivor/. It is separate from the original game’s own account and privacy practices.</p><h2>Hosting and delivery</h2><p>Cloudflare provides hosting and security. It may process technical request data such as IP address, browser details and the requested URL. Cloudflare may automatically add Web Analytics or performance measurement to pages, including error responses, and process technical request and performance data. See {ext("https://www.cloudflare.com/privacypolicy/","Cloudflare’s privacy policy")}.</p><h2>Advertising and website scripts</h2><p>The section homepage and ordinary gameplay guides load this website’s Google AdSense code. Google and its advertising partners may make requests and use cookies or device information for advertising and measurement. About, Contact, this Privacy page and error pages do not load our advertising code. This section adds no Google Analytics tag or other new analytics service.</p><p>Fonts, diagrams and title-screen media are hosted by this website. The guide navigation and collapsible menus use native HTML. The <a href="{P}play/">Play page</a> uses a local script for click-to-load, expanded view and hiding/restoring the same game frame. These display controls do not store your game collection. The third-party game does not load until you press Play. Once loaded, pokesurvivor.pro, r2.pokennection.org and jsDelivr supply the game and its resources. The embedded provider also requests Google Tag Manager and Cloudflare performance code; these are inside the third-party game, separate from our guide scripts. The provider may contact account and game-data services and use browser storage, cookies and technical request information. Its embedded sign-in and guest features are operated by that provider, not Megabonk.org. Read the host’s legal/privacy notice inside the game before signing in; account and save compatibility with pokesurvivor.com is not established. Opening an external game or download page also connects to that provider under its own practices.</p><h2>Advertising choices</h2><p>Review {ext("https://policies.google.com/technologies/ads","Google’s advertising privacy information")} and {ext("https://myadcenter.google.com/","Google My Ad Center")}. Where provided, Google’s consent messages offer applicable choices. This notice is not a promise that the whole domain makes no third-party requests.</p><h2>Email</h2><p>Email sent to qsyhxw@gmail.com is processed through Gmail. The publisher receives the sender address and details you include to handle the request. Send no passwords or account tokens. You can request deletion of correspondence at the same address, subject to necessary record retention.</p><h2>Other sections and external services</h2><p>Other Megabonk.org sections can load Google Analytics or different functional scripts and have a <a href="/privacy-policy">site-wide privacy policy</a>. External original-game accounts, cloud saves, download hosts, GitHub and Reddit are not controlled by this guide publisher. Check the destination’s notice before signing in.</p><p>Questions: <a href="{P}contact/">contact the publisher</a>. This notice will change if services in this section change.</p>'
    begin('404','Page Not Found | Poke Survivor Guide','This trail ends here.','This Poke Survivor guide address was not found. Return to the field guide or choose an available topic from the guide index.',diagram=None,kind='error')
    current['body']=f'<p>The page may have moved, or the address may be incomplete.</p><div class="actions"><a class="button" href="{P}">Back to PokéSurvivor →</a><a class="button secondary" href="{P}#guides">Choose a guide</a></div>'
    return pages

